package com.leko.forge.msi.jvm

import com.leko.forge.msi.Interpreter

/** A function value in code generated by [toJvm]: lambdas and function references implement it. */
public fun interface MsiFunction {
    public fun invoke(args: Array<Any?>): Any?
}

/** Carries a thrown MSI value through the JVM exception mechanism. */
public class MsiThrowable(public val value: Any?) : RuntimeException("MSI exception: $value", null, false, false)

/** Helpers called by generated code. */
public object MsiRuntime {
    /** Doubles as text, as the [Interpreter] formats them. */
    @JvmStatic
    public fun str(value: Double): String = Interpreter.formatDouble(value)

    /** Calls the host implementation of an external function. */
    @JvmStatic
    public fun external(externals: Map<String, (List<Any?>) -> Any?>?, name: String, args: Array<Any?>): Any? {
        val implementation = externals?.get(name) ?: throw IllegalStateException("no implementation for external fun $name")
        return implementation(args.toList())
    }
}

/** A reference created by `Borrow` in code generated by [toJvm]. */
public interface MsiRef {
    public fun get(): Any?
    public fun set(value: Any?)
}

/** A reference to a local variable, kept in a one element box. */
public class BoxRef(private val box: Array<Any?>) : MsiRef {
    override fun get(): Any? = box[0]
    override fun set(value: Any?) { box[0] = value }
}

/** A reference to a field of a struct instance. */
public class FieldRef(private val target: Any, name: String) : MsiRef {
    private val field = target.javaClass.getField(name)
    override fun get(): Any? = field.get(target)
    override fun set(value: Any?) { field.set(target, value) }
}

/** Runtime checks of `Access`: readers and writers per object. */
public object MsiAccess {
    private class Count { var readers = 0; var writing = false }
    private val counts = ThreadLocal.withInitial { java.util.IdentityHashMap<Any, Count>() }

    @JvmStatic
    public fun begin(target: Any?, mutable: Boolean) {
        val count = counts.get().getOrPut(target ?: throw IllegalStateException("access to an uninitialized value")) { Count() }
        if (count.writing || mutable && count.readers > 0)
            throw com.leko.forge.msi.MsiRuntimeException("simultaneous access: it is already ${if (count.writing) "being modified" else "being read"}")
        if (mutable) count.writing = true else count.readers++
    }

    @JvmStatic
    public fun end(target: Any?, mutable: Boolean) {
        val count = counts.get()[target] ?: return
        if (mutable) count.writing = false else count.readers--
    }
}
